mapper.select:
SELECT request_hash AS requestHash, result_type AS resultType, lease_owner AS leaseOwner,
       lease_version AS leaseVersion
FROM mk_award_intent_dedupe
WHERE tenant_id = #{tenantId} AND source_system = #{sourceSystem}
  AND source_request_id = #{sourceRequestId}
FOR UPDATE

SELECT request_hash AS requestHash, result_type AS resultType, lease_until AS leaseUntil,
       lease_version AS leaseVersion
FROM mk_award_intent_dedupe
WHERE tenant_id = #{tenantId} AND source_system = #{sourceSystem}
  AND source_request_id = #{sourceRequestId}

mapper.update:
UPDATE mk_award_intent_dedupe
SET lease_owner = #{leaseOwner}, lease_until = #{leaseUntil}, lease_version = #{nextLeaseVersion},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND source_system = #{sourceSystem}
  AND source_request_id = #{sourceRequestId} AND request_hash = #{requestHash}
  AND result_type = 'PROCESSING' AND lease_version = #{expectedLeaseVersion}
  AND lease_until <= #{now}

UPDATE mk_award_intent_dedupe
SET result_type = #{resultType}, lease_owner = NULL, lease_until = NULL, updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId} AND source_system = #{sourceSystem}
  AND source_request_id = #{sourceRequestId} AND result_type = 'PROCESSING'
  AND lease_owner = #{leaseOwner} AND lease_version = #{leaseVersion}

mapper.delete:
DELETE FROM mk_award_intent_dedupe
WHERE tenant_id = #{tenantId} AND source_system = #{sourceSystem}
  AND source_request_id = #{sourceRequestId} AND result_type = 'PROCESSING'
  AND lease_owner = #{leaseOwner} AND lease_version = #{leaseVersion}

