SELECT *
FROM (
    SELECT 
    FROM mk_award_intent_outbox
    WHERE tenant_id = #{tenantId} AND campaign_id = #{campaignId}
    UNION ALL
    SELECT 
    FROM mk_award_intent_block
    WHERE tenant_id = #{tenantId} AND campaign_id = #{campaignId}
) combined

    WHERE createdAt < #{createdBefore}
       OR (createdAt = #{createdBefore} AND intentId < #{cursorIntentId})

ORDER BY createdAt DESC, intentId DESC
LIMIT #{limit}
